function maxRemovable(pins: number[][]): number {
  const n = pins.length;
  const seen = new Array<boolean>(n).fill(false);
  let groups = 0;
  for (let s = 0; s < n; s++) {
    if (seen[s]) continue;
    groups++;
    seen[s] = true;
    const stack = [s];
    while (stack.length) {
      const i = stack.pop()!;
      for (let j = 0; j < n; j++) {
        if (!seen[j] && (pins[i][0] === pins[j][0] || pins[i][1] === pins[j][1])) {
          seen[j] = true;
          stack.push(j);
        }
      }
    }
  }
  return n - groups;
}

