    def maxRemovable(self, pins: List[List[int]]) -> int:
        n = len(pins)
        seen = [False] * n
        groups = 0
        for s in range(n):
            if seen[s]:
                continue
            groups += 1
            seen[s] = True
            stack = [s]
            while stack:
                i = stack.pop()
                for j in range(n):
                    if not seen[j] and (pins[i][0] == pins[j][0] or pins[i][1] == pins[j][1]):
                        seen[j] = True
                        stack.append(j)
        return n - groups

