function maxRemovable(pins: number[][]): number {
  const parent = new Map<number, number>();
  const find = (x: number): number => {
    if (!parent.has(x)) parent.set(x, x);
    let root = x;
    while (parent.get(root) !== root) root = parent.get(root)!;
    while (x !== root) { const next = parent.get(x)!; parent.set(x, root); x = next; }
    return root;
  };
  for (const [r, c] of pins) parent.set(find(r), find(c + 10001));
  const roots = new Set<number>();
  for (const key of parent.keys()) roots.add(find(key));
  return pins.length - roots.size;
}

